        int current = 0;
        SegmentTree[] dp = {new SegmentTree(N + 1), new SegmentTree(N + 1)};
        dp[0].assign(0, 0);
        for (int[] interval : intervals) {
            for (int j = N; j >= 0; j--) {
                dp[0].assign(j, dp[0].getVal(j - (interval[0] - current)));
            }
            current = interval[1];
            int size = interval[1] - interval[0];
            for (int j = N; j >= 0; j--) {
                int[] minVals = new int[2];
                for (int z = 0; z <= 1; z++) {
                    int twoSwaps = dp[z].query(j - size, j);
                    int oneSwap = dp[(z + 1) % 2].query(j - size, j);
                    int noSwap;
                    if (z == 1) {
                        noSwap = dp[z].getVal(j);
