                if (index <= mid) {
                    node = node * 2;
                    end = mid;
                } else {
                    node = node * 2 + 1;
                    start = mid + 1;
                }
            }
            tree[node] = value;
            node /= 2;
            while (node > 0) {
                tree[node] = Math.min(tree[node * 2], tree[node * 2 + 1]);
